export const INDEX_HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <title>模擬ヒアリング</title>\n  <style>\n    :root {\n      color-scheme: light dark;\n      --bg: #f4f6f8;\n      --surface: #ffffff;\n      --surface-2: #eef1f5;\n      --text: #1b2430;\n      --muted: #5b6776;\n      --line: #d9dfe7;\n      --accent: #1f6feb;\n      --accent-text: #ffffff;\n      --user-bg: #1f6feb;\n      --user-text: #ffffff;\n      --warn-bg: #fff4d6;\n      --warn-text: #6b4b00;\n      --danger-bg: #fde8e8;\n      --danger-text: #8a1c1c;\n      --ok-bg: #e3f5e9;\n      --ok-text: #14532d;\n    }\n    @media (prefers-color-scheme: dark) {\n      :root {\n        --bg: #0f141a;\n        --surface: #18202a;\n        --surface-2: #212b37;\n        --text: #e8edf3;\n        --muted: #9aa7b6;\n        --line: #2c3745;\n        --accent: #5aa2ff;\n        --accent-text: #08111c;\n        --user-bg: #2a5fb8;\n        --user-text: #ffffff;\n        --warn-bg: #3a2f10;\n        --warn-text: #ffdf8a;\n        --danger-bg: #3d1c1c;\n        --danger-text: #ffb4b4;\n        --ok-bg: #12301f;\n        --ok-text: #a8e6bd;\n      }\n    }\n    * { box-sizing: border-box; }\n    html, body { height: 100%; }\n    body {\n      margin: 0;\n      background: var(--bg);\n      color: var(--text);\n      font: 15px/1.65 -apple-system, BlinkMacSystemFont, \"Hiragino Sans\", \"Hiragino Kaku Gothic ProN\", \"Yu Gothic UI\", Meiryo, sans-serif;\n      display: flex;\n      flex-direction: column;\n    }\n    [hidden] { display: none !important; }\n    button, input, textarea { font: inherit; color: inherit; }\n    :focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }\n\n    header.top {\n      display: flex; align-items: center; justify-content: space-between; gap: 12px;\n      padding: 12px 20px; background: var(--surface); border-bottom: 1px solid var(--line);\n    }\n    header.top h1 { margin: 0; font-size: 17px; letter-spacing: .02em; }\n    .who { color: var(--muted); font-size: 14px; }\n    .who b { color: var(--text); font-weight: 600; }\n\n    .notice {\n      margin: 0; padding: 8px 20px; font-size: 13px; color: var(--muted);\n      background: var(--surface); border-top: 1px solid var(--line);\n    }\n\n    /* ---- ログイン ---- */\n    .login-wrap { flex: 1; display: grid; place-items: center; padding: 24px 16px; }\n    .card {\n      width: min(440px, 100%); background: var(--surface); border: 1px solid var(--line);\n      border-radius: 14px; padding: 28px; box-shadow: 0 1px 2px rgba(0,0,0,.04);\n    }\n    .card h2 { margin: 0 0 4px; font-size: 20px; }\n    .card p.lead { margin: 0 0 20px; color: var(--muted); }\n    label { display: block; margin: 14px 0 4px; font-weight: 600; font-size: 14px; }\n    .field {\n      width: 100%; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px;\n      background: var(--bg);\n    }\n    .field:focus { border-color: var(--accent); }\n    .btn {\n      appearance: none; border: 1px solid var(--line); background: var(--surface-2); color: var(--text);\n      padding: 9px 14px; border-radius: 8px; cursor: pointer; font-weight: 600;\n    }\n    .btn:hover:not(:disabled) { filter: brightness(0.97); }\n    .btn:disabled { opacity: .5; cursor: not-allowed; }\n    .btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-text); }\n    .btn.block { width: 100%; margin-top: 20px; padding: 11px 14px; }\n    .privacy {\n      margin-top: 18px; padding: 10px 12px; background: var(--warn-bg); color: var(--warn-text);\n      border-radius: 8px; font-size: 13px;\n    }\n    .form-error { margin-top: 12px; color: var(--danger-text); background: var(--danger-bg); padding: 8px 12px; border-radius: 8px; font-size: 14px; }\n\n    /* ---- チャット ---- */\n    .app { flex: 1; min-height: 0; display: grid; grid-template-columns: 250px 1fr; }\n    aside.side {\n      background: var(--surface); border-right: 1px solid var(--line); padding: 16px;\n      display: flex; flex-direction: column; gap: 14px; overflow-y: auto;\n    }\n    aside.side h2 { margin: 0; font-size: 13px; color: var(--muted); font-weight: 600; }\n    .personas { display: flex; flex-direction: column; gap: 8px; }\n    .persona-btn {\n      text-align: left; width: 100%; padding: 10px 12px; border-radius: 10px; cursor: pointer;\n      border: 1px solid var(--line); background: var(--bg);\n    }\n    .persona-btn .name { display: block; font-weight: 600; }\n    .persona-btn .desc { display: block; font-size: 12px; color: var(--muted); }\n    .persona-btn[aria-selected=\"true\"] { border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); background: var(--surface); }\n    .persona-btn:disabled { cursor: not-allowed; opacity: .6; }\n    .remaining { font-size: 14px; padding: 8px 12px; border-radius: 8px; background: var(--surface-2); }\n    .remaining.low { background: var(--warn-bg); color: var(--warn-text); }\n    .remaining.none { background: var(--danger-bg); color: var(--danger-text); }\n    .side-actions { display: flex; flex-direction: column; gap: 8px; margin-top: auto; }\n    .side-actions a.btn { text-decoration: none; text-align: center; }\n    .side-actions a.btn[aria-disabled=\"true\"] { opacity: .5; pointer-events: none; }\n\n    main.chat { display: flex; flex-direction: column; min-width: 0; min-height: 0; }\n    .chat-head { padding: 12px 20px; border-bottom: 1px solid var(--line); background: var(--surface); }\n    .chat-head .name { font-weight: 700; }\n    .chat-head .desc { color: var(--muted); font-size: 13px; }\n    .banner { margin: 0; padding: 10px 20px; font-size: 14px; }\n    .banner.error { background: var(--danger-bg); color: var(--danger-text); }\n    .banner.info { background: var(--ok-bg); color: var(--ok-text); }\n\n    .log { flex: 1; min-height: 0; overflow-y: auto; padding: 20px; display: flex; flex-direction: column; gap: 14px; }\n    .empty { margin: auto; max-width: 420px; text-align: center; color: var(--muted); }\n    .msg { max-width: min(680px, 86%); display: flex; flex-direction: column; gap: 2px; }\n    .msg .who-label { font-size: 12px; color: var(--muted); }\n    .msg .bubble {\n      padding: 10px 14px; border-radius: 14px; white-space: pre-wrap; overflow-wrap: anywhere;\n      background: var(--surface); border: 1px solid var(--line); border-top-left-radius: 4px;\n    }\n    .msg.user { align-self: flex-end; align-items: flex-end; }\n    .msg.user .bubble { background: var(--user-bg); border-color: var(--user-bg); color: var(--user-text); border-top-left-radius: 14px; border-top-right-radius: 4px; }\n    .typing { display: inline-flex; gap: 4px; align-items: center; height: 1.4em; }\n    .typing i { width: 6px; height: 6px; border-radius: 50%; background: var(--muted); animation: blink 1.2s infinite ease-in-out; }\n    .typing i:nth-child(2) { animation-delay: .2s; }\n    .typing i:nth-child(3) { animation-delay: .4s; }\n    @keyframes blink { 0%, 80%, 100% { opacity: .25; } 40% { opacity: 1; } }\n    @media (prefers-reduced-motion: reduce) { .typing i { animation: none; opacity: .6; } }\n\n    form.composer { display: flex; gap: 10px; align-items: flex-end; padding: 12px 20px 8px; background: var(--surface); border-top: 1px solid var(--line); }\n    .composer textarea { flex: 1; resize: none; min-height: 46px; max-height: 160px; }\n    .counter { font-size: 12px; color: var(--muted); text-align: right; padding: 0 20px 8px; background: var(--surface); }\n    .composer-wrap { background: var(--surface); }\n    .counter.over { color: var(--danger-text); font-weight: 700; }\n\n    @media (max-width: 760px) {\n      .app { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }\n      aside.side { border-right: 0; border-bottom: 1px solid var(--line); flex-direction: row; flex-wrap: wrap; align-items: center; padding: 10px 12px; gap: 8px; }\n      aside.side h2 { display: none; }\n      .personas { flex-direction: row; flex: 1 1 100%; }\n      .persona-btn { padding: 8px 10px; }\n      .persona-btn .desc { display: none; }\n      .side-actions { flex-direction: row; margin: 0; }\n      .msg { max-width: 94%; }\n      header.top { padding: 10px 12px; }\n      .log, .chat-head, .banner { padding-left: 12px; padding-right: 12px; }\n      form.composer { padding-left: 12px; padding-right: 12px; }\n      .counter { padding-right: 12px; }\n    }\n  </style>\n</head>\n<body>\n  <header class=\"top\">\n    <h1>模擬ヒアリング</h1>\n    <div class=\"who\" id=\"who\" hidden>名前：<b id=\"who-name\"></b></div>\n  </header>\n\n  <!-- 最初の画面: 合言葉と名前 -->\n  <section class=\"login-wrap\" id=\"login-view\" hidden>\n    <form class=\"card\" id=\"login-form\" autocomplete=\"off\">\n      <h2>はじめに</h2>\n      <p class=\"lead\">講師から伝えられた合言葉と、あなたの名前を入力してください。</p>\n      <label for=\"code\">合言葉</label>\n      <input class=\"field\" id=\"code\" type=\"password\" required autocomplete=\"off\" spellcheck=\"false\">\n      <label for=\"name\">名前（ログの区別にだけ使います）</label>\n      <input class=\"field\" id=\"name\" type=\"text\" required maxlength=\"30\" autocomplete=\"off\" placeholder=\"例：田中\">\n      <p class=\"privacy\">入力した内容は講師が確認します。個人情報や社外秘の情報は入力しないでください。</p>\n      <div class=\"form-error\" id=\"login-error\" role=\"alert\" hidden></div>\n      <button class=\"btn primary block\" id=\"login-submit\" type=\"submit\">はじめる</button>\n    </form>\n  </section>\n\n  <!-- チャット画面 -->\n  <div class=\"app\" id=\"app-view\" hidden>\n    <aside class=\"side\">\n      <h2 id=\"persona-heading\">相手を選ぶ</h2>\n      <div class=\"personas\" id=\"personas\" role=\"tablist\" aria-labelledby=\"persona-heading\"></div>\n      <div class=\"remaining\" id=\"remaining\" aria-live=\"polite\"></div>\n      <div class=\"side-actions\">\n        <button class=\"btn\" id=\"reset-btn\" type=\"button\">やり直す</button>\n        <a class=\"btn\" id=\"export-btn\" href=\"#\" download>会話を保存</a>\n      </div>\n    </aside>\n\n    <main class=\"chat\">\n      <div class=\"chat-head\">\n        <div class=\"name\" id=\"chat-name\"></div>\n        <div class=\"desc\" id=\"chat-desc\"></div>\n      </div>\n      <p class=\"banner error\" id=\"banner\" role=\"alert\" hidden></p>\n      <div class=\"log\" id=\"log\" role=\"log\" aria-live=\"polite\" aria-label=\"会話\"></div>\n      <div class=\"composer-wrap\">\n        <form class=\"composer\" id=\"composer\">\n          <textarea class=\"field\" id=\"input\" rows=\"2\" aria-label=\"質問を入力\" placeholder=\"質問を入力（Enterで送信、Shift+Enterで改行）\"></textarea>\n          <button class=\"btn primary\" id=\"send\" type=\"submit\">送信</button>\n        </form>\n        <div class=\"counter\" id=\"counter\" aria-hidden=\"true\"></div>\n      </div>\n    </main>\n  </div>\n\n  <p class=\"notice\">※ 入力した内容は講師が確認します。個人情報や社外秘は入力しないでください。</p>\n\n  <script>\n    \"use strict\";\n\n    const $ = (id) => document.getElementById(id);\n    const els = {\n      loginView: $(\"login-view\"), appView: $(\"app-view\"), who: $(\"who\"), whoName: $(\"who-name\"),\n      loginForm: $(\"login-form\"), code: $(\"code\"), name: $(\"name\"), loginError: $(\"login-error\"), loginSubmit: $(\"login-submit\"),\n      personas: $(\"personas\"), remaining: $(\"remaining\"), resetBtn: $(\"reset-btn\"), exportBtn: $(\"export-btn\"),\n      chatName: $(\"chat-name\"), chatDesc: $(\"chat-desc\"), banner: $(\"banner\"), log: $(\"log\"),\n      composer: $(\"composer\"), input: $(\"input\"), send: $(\"send\"), counter: $(\"counter\"),\n    };\n\n    const state = {\n      personas: [], maxTurns: 20, maxChars: 500,\n      current: null, busy: false,\n      // 相手ごとの会話。サーバーが正で、ここは表示用の写し / Per-persona copy for display; the server is the source of truth\n      convs: {},\n    };\n\n    const codePoints = (text) => Array.from(text).length;\n\n    async function api(path, options = {}) {\n      const res = await fetch(path, {\n        ...options,\n        headers: { \"Content-Type\": \"application/json\", ...(options.headers || {}) },\n      });\n      return res;\n    }\n\n    async function errorMessage(res) {\n      try {\n        const data = await res.json();\n        return data && data.error && data.error.message ? data.error.message : \"エラーが発生しました。もう一度試してください\";\n      } catch {\n        return \"エラーが発生しました。もう一度試してください\";\n      }\n    }\n\n    // ---------- 画面の切り替え ----------\n    function showLogin(message) {\n      els.appView.hidden = true;\n      els.who.hidden = true;\n      els.loginView.hidden = false;\n      els.loginError.hidden = !message;\n      els.loginError.textContent = message || \"\";\n      els.code.focus();\n    }\n\n    async function showApp(name) {\n      els.loginView.hidden = true;\n      els.appView.hidden = false;\n      els.who.hidden = false;\n      els.whoName.textContent = name;\n\n      const res = await api(\"/api/personas\");\n      if (res.status === 401) return showLogin();\n      if (!res.ok) return showLogin(await errorMessage(res));\n      const data = await res.json();\n      state.personas = data.personas;\n      state.maxTurns = data.maxTurns;\n      state.maxChars = data.maxMessageChars;\n\n      await Promise.all(state.personas.map((p) => loadHistory(p.id)));\n      renderPersonas();\n      selectPersona(state.current && state.personas.some((p) => p.id === state.current) ? state.current : state.personas[0].id);\n    }\n\n    async function loadHistory(personaId) {\n      const res = await api(`/api/chat/${encodeURIComponent(personaId)}`);\n      if (res.status === 401) return showLogin();\n      if (!res.ok) return;\n      const data = await res.json();\n      state.convs[personaId] = { messages: data.messages, remaining: data.remaining };\n    }\n\n    // ---------- 描画 ----------\n    function renderPersonas() {\n      els.personas.textContent = \"\";\n      for (const persona of state.personas) {\n        const button = document.createElement(\"button\");\n        button.type = \"button\";\n        button.className = \"persona-btn\";\n        button.setAttribute(\"role\", \"tab\");\n        button.dataset.id = persona.id;\n        const name = document.createElement(\"span\");\n        name.className = \"name\";\n        name.textContent = persona.name;\n        const desc = document.createElement(\"span\");\n        desc.className = \"desc\";\n        desc.textContent = persona.description;\n        button.append(name, desc);\n        button.addEventListener(\"click\", () => selectPersona(persona.id));\n        els.personas.append(button);\n      }\n    }\n\n    function currentPersona() {\n      return state.personas.find((p) => p.id === state.current);\n    }\n\n    function selectPersona(id) {\n      if (state.busy) return;\n      state.current = id;\n      for (const button of els.personas.children) {\n        button.setAttribute(\"aria-selected\", String(button.dataset.id === id));\n      }\n      const persona = currentPersona();\n      els.chatName.textContent = persona.name;\n      els.chatDesc.textContent = persona.description;\n      els.exportBtn.href = `/api/chat/${encodeURIComponent(id)}/export`;\n      hideBanner();\n      renderMessages();\n      renderRemaining();\n      els.input.focus();\n    }\n\n    function addMessageEl(role, text, pending) {\n      const wrap = document.createElement(\"div\");\n      wrap.className = `msg ${role}`;\n      const label = document.createElement(\"div\");\n      label.className = \"who-label\";\n      label.textContent = role === \"user\" ? \"あなた\" : currentPersona().name;\n      const bubble = document.createElement(\"div\");\n      bubble.className = \"bubble\";\n      if (pending && !text) bubble.append(typingDots());\n      else bubble.textContent = text;\n      wrap.append(label, bubble);\n      els.log.append(wrap);\n      els.log.scrollTop = els.log.scrollHeight;\n      return bubble;\n    }\n\n    function typingDots() {\n      const dots = document.createElement(\"span\");\n      dots.className = \"typing\";\n      dots.setAttribute(\"aria-label\", \"返答を作成中\");\n      dots.append(document.createElement(\"i\"), document.createElement(\"i\"), document.createElement(\"i\"));\n      return dots;\n    }\n\n    function renderMessages() {\n      els.log.textContent = \"\";\n      const conv = state.convs[state.current];\n      if (!conv || conv.messages.length === 0) {\n        const empty = document.createElement(\"div\");\n        empty.className = \"empty\";\n        empty.textContent = `${currentPersona().name}に、資料に書かれていないことを質問してみましょう。`;\n        els.log.append(empty);\n        return;\n      }\n      for (const message of conv.messages) addMessageEl(message.role, message.text, false);\n    }\n\n    function renderRemaining() {\n      const conv = state.convs[state.current];\n      const remaining = conv ? conv.remaining : state.maxTurns;\n      els.remaining.textContent = remaining > 0 ? `残り：${remaining}回` : \"上限に達しました\";\n      els.remaining.className = `remaining${remaining === 0 ? \" none\" : remaining <= 5 ? \" low\" : \"\"}`;\n      updateControls();\n    }\n\n    function updateControls() {\n      const conv = state.convs[state.current];\n      const remaining = conv ? conv.remaining : state.maxTurns;\n      const length = codePoints(els.input.value.trim());\n      const tooLong = length > state.maxChars;\n      els.counter.textContent = `${length} / ${state.maxChars}`;\n      els.counter.classList.toggle(\"over\", tooLong);\n      els.send.disabled = state.busy || remaining === 0 || length === 0 || tooLong;\n      els.input.disabled = state.busy || remaining === 0;\n      els.input.placeholder = remaining === 0\n        ? \"この相手との往復の上限に達しました。「やり直す」で最初から始められます\"\n        : \"質問を入力（Enterで送信、Shift+Enterで改行）\";\n      els.resetBtn.disabled = state.busy;\n      for (const button of els.personas.children) button.disabled = state.busy;\n      const hasMessages = Boolean(conv && conv.messages.length > 0);\n      els.exportBtn.setAttribute(\"aria-disabled\", String(!hasMessages || state.busy));\n    }\n\n    function showBanner(message) {\n      els.banner.textContent = message;\n      els.banner.hidden = false;\n    }\n    function hideBanner() {\n      els.banner.hidden = true;\n      els.banner.textContent = \"\";\n    }\n\n    // ---------- 送信（SSEを読む） ----------\n    async function sendMessage() {\n      const text = els.input.value.trim();\n      const personaId = state.current;\n      if (!text || state.busy) return;\n\n      hideBanner();\n      state.busy = true;\n      updateControls();\n\n      // 初回は案内文を消す / drop the empty-state hint on first message\n      const empty = els.log.querySelector(\".empty\");\n      if (empty) empty.remove();\n      addMessageEl(\"user\", text, false);\n      const bubble = addMessageEl(\"assistant\", \"\", true);\n      let streamed = \"\";\n      let finished = false;\n\n      try {\n        const res = await api(`/api/chat/${encodeURIComponent(personaId)}`, {\n          method: \"POST\",\n          body: JSON.stringify({ message: text }),\n        });\n\n        if (res.status === 401) {\n          showLogin(\"接続が切れました。もう一度、合言葉と名前を入力してください。\");\n          return;\n        }\n        const type = res.headers.get(\"content-type\") || \"\";\n        if (!res.ok || !type.includes(\"text/event-stream\")) {\n          throw new Error(await errorMessage(res));\n        }\n\n        const reader = res.body.getReader();\n        const decoder = new TextDecoder();\n        let buffer = \"\";\n\n        const handle = (event, data) => {\n          if (event === \"delta\") {\n            streamed += data.text;\n            bubble.textContent = streamed;\n            els.log.scrollTop = els.log.scrollHeight;\n          } else if (event === \"reset\") {\n            streamed = \"\";\n            bubble.textContent = \"\";\n            bubble.append(typingDots());\n          } else if (event === \"done\") {\n            finished = true;\n            bubble.textContent = data.text;\n            const conv = state.convs[personaId] || { messages: [], remaining: state.maxTurns };\n            conv.messages.push({ role: \"user\", text }, { role: \"assistant\", text: data.text });\n            conv.remaining = data.remaining;\n            state.convs[personaId] = conv;\n            els.input.value = \"\";\n            els.input.style.height = \"auto\";\n          } else if (event === \"error\") {\n            throw new Error(data.message);\n          }\n        };\n\n        for (;;) {\n          const { value, done } = await reader.read();\n          if (done) break;\n          buffer += decoder.decode(value, { stream: true });\n          let boundary;\n          while ((boundary = buffer.indexOf(\"\\n\\n\")) !== -1) {\n            const block = buffer.slice(0, boundary);\n            buffer = buffer.slice(boundary + 2);\n            const eventLine = block.split(\"\\n\").find((line) => line.startsWith(\"event:\"));\n            const dataLine = block.split(\"\\n\").find((line) => line.startsWith(\"data:\"));\n            if (!eventLine || !dataLine) continue;\n            handle(eventLine.slice(6).trim(), JSON.parse(dataLine.slice(5).trim()));\n          }\n        }\n        if (!finished) throw new Error(\"通信が途切れました。もう一度送ってください\");\n      } catch (error) {\n        // 失敗した発言は履歴に残らない。入力欄へ戻して、サーバーの状態に表示を合わせる\n        // A failed message is not persisted: put it back in the box and re-sync the view with the server\n        showBanner(error instanceof Error ? error.message : \"エラーが発生しました。もう一度送ってください\");\n        await loadHistory(personaId);\n      } finally {\n        state.busy = false;\n        if (state.current === personaId) {\n          renderMessages();\n          renderRemaining();\n          els.input.focus();\n        }\n        updateControls();\n      }\n    }\n\n    // ---------- 操作 ----------\n    els.loginForm.addEventListener(\"submit\", async (event) => {\n      event.preventDefault();\n      els.loginSubmit.disabled = true;\n      els.loginError.hidden = true;\n      try {\n        const res = await api(\"/api/session\", {\n          method: \"POST\",\n          body: JSON.stringify({ code: els.code.value, name: els.name.value }),\n        });\n        if (!res.ok) {\n          els.loginError.textContent = await errorMessage(res);\n          els.loginError.hidden = false;\n          return;\n        }\n        const data = await res.json();\n        els.code.value = \"\";\n        await showApp(data.name);\n      } catch {\n        els.loginError.textContent = \"通信に失敗しました。もう一度試してください\";\n        els.loginError.hidden = false;\n      } finally {\n        els.loginSubmit.disabled = false;\n      }\n    });\n\n    els.composer.addEventListener(\"submit\", (event) => {\n      event.preventDefault();\n      sendMessage();\n    });\n\n    els.input.addEventListener(\"input\", () => {\n      updateControls();\n      els.input.style.height = \"auto\";\n      els.input.style.height = `${Math.min(els.input.scrollHeight, 160)}px`;\n    });\n\n    els.input.addEventListener(\"keydown\", (event) => {\n      // 日本語入力の変換確定のEnterでは送信しない / Do not send on the Enter that confirms IME composition\n      if (event.key === \"Enter\" && !event.shiftKey && !event.isComposing && event.keyCode !== 229) {\n        event.preventDefault();\n        if (!els.send.disabled) sendMessage();\n      }\n    });\n\n    els.resetBtn.addEventListener(\"click\", async () => {\n      const persona = currentPersona();\n      if (!persona || state.busy) return;\n      if (!window.confirm(`「${persona.name}」との会話を最初からやり直しますか？\\nこれまでの会話は画面から消えます（講師の記録には残ります）。`)) return;\n      const res = await api(`/api/chat/${encodeURIComponent(persona.id)}/reset`, { method: \"POST\", body: \"{}\" });\n      if (res.status === 401) return showLogin();\n      if (!res.ok) return showBanner(await errorMessage(res));\n      const data = await res.json();\n      state.convs[persona.id] = { messages: [], remaining: data.remaining };\n      hideBanner();\n      renderMessages();\n      renderRemaining();\n    });\n\n    els.exportBtn.addEventListener(\"click\", (event) => {\n      if (els.exportBtn.getAttribute(\"aria-disabled\") === \"true\") event.preventDefault();\n    });\n\n    // ---------- 起動 ----------\n    (async function init() {\n      try {\n        const res = await api(\"/api/session\");\n        if (res.ok) {\n          const data = await res.json();\n          await showApp(data.name);\n        } else {\n          showLogin();\n        }\n      } catch {\n        showLogin(\"通信に失敗しました。ページを開き直してください\");\n      }\n    })();\n  </script>\n</body>\n</html>\n";

export const ADMIN_HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <title>模擬ヒアリング 講師の画面</title>\n  <style>\n    :root {\n      color-scheme: light dark;\n      --bg: #f4f6f8;\n      --surface: #ffffff;\n      --surface-2: #eef1f5;\n      --text: #1b2430;\n      --muted: #5b6776;\n      --line: #d9dfe7;\n      --accent: #1f6feb;\n      --accent-text: #ffffff;\n      --user-bg: #1f6feb;\n      --user-text: #ffffff;\n      --warn-bg: #fff4d6;\n      --warn-text: #6b4b00;\n      --danger: #c62828;\n      --danger-bg: #fde8e8;\n      --danger-text: #8a1c1c;\n      --ok-bg: #e3f5e9;\n      --ok-text: #14532d;\n    }\n    @media (prefers-color-scheme: dark) {\n      :root {\n        --bg: #0f141a; --surface: #18202a; --surface-2: #212b37; --text: #e8edf3; --muted: #9aa7b6;\n        --line: #2c3745; --accent: #5aa2ff; --accent-text: #08111c; --user-bg: #2a5fb8; --user-text: #ffffff;\n        --warn-bg: #3a2f10; --warn-text: #ffdf8a; --danger: #ef5350; --danger-bg: #3d1c1c; --danger-text: #ffb4b4;\n        --ok-bg: #12301f; --ok-text: #a8e6bd;\n      }\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0; background: var(--bg); color: var(--text);\n      font: 15px/1.6 -apple-system, BlinkMacSystemFont, \"Hiragino Sans\", \"Hiragino Kaku Gothic ProN\", \"Yu Gothic UI\", Meiryo, sans-serif;\n    }\n    [hidden] { display: none !important; }\n    button, input, a { font: inherit; color: inherit; }\n    :focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }\n\n    header.top { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 20px; background: var(--surface); border-bottom: 1px solid var(--line); }\n    header.top h1 { margin: 0; font-size: 17px; }\n    .muted { color: var(--muted); }\n    .btn {\n      appearance: none; border: 1px solid var(--line); background: var(--surface-2); color: var(--text);\n      padding: 8px 14px; border-radius: 8px; cursor: pointer; font-weight: 600; text-decoration: none; display: inline-block;\n    }\n    .btn:disabled { opacity: .5; cursor: not-allowed; }\n    .btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-text); }\n    .btn.danger { background: var(--danger); border-color: var(--danger); color: #fff; }\n    .field { padding: 9px 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--bg); }\n\n    .login-wrap { display: grid; place-items: center; min-height: 70vh; padding: 24px 16px; }\n    .card { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 22px; }\n    .login-card { width: min(420px, 100%); padding: 28px; }\n    .login-card h2 { margin: 0 0 16px; font-size: 20px; }\n    .login-card label { display: block; margin: 0 0 4px; font-weight: 600; font-size: 14px; }\n    .login-card .field { width: 100%; }\n    .login-card .btn { width: 100%; margin-top: 16px; padding: 11px; }\n    .form-error { margin-top: 12px; color: var(--danger-text); background: var(--danger-bg); padding: 8px 12px; border-radius: 8px; font-size: 14px; }\n\n    .wrap { max-width: 1180px; margin: 0 auto; padding: 20px; display: grid; gap: 16px; }\n    .banner { padding: 12px 16px; border-radius: 10px; font-weight: 600; }\n    .banner.danger { background: var(--danger-bg); color: var(--danger-text); border: 1px solid var(--danger); }\n    .banner.warn { background: var(--warn-bg); color: var(--warn-text); }\n    .banner small { display: block; font-weight: 400; margin-top: 2px; overflow-wrap: anywhere; }\n\n    .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }\n    .card h2 { margin: 0 0 10px; font-size: 14px; color: var(--muted); font-weight: 600; }\n    .big { font-size: 26px; font-weight: 700; line-height: 1.2; }\n    .kv { display: grid; grid-template-columns: auto 1fr; gap: 2px 12px; font-size: 14px; margin-top: 10px; }\n    .kv dt { color: var(--muted); }\n    .kv dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; }\n    .bar { height: 10px; background: var(--surface-2); border-radius: 999px; overflow: hidden; margin-top: 10px; }\n    .bar > i { display: block; height: 100%; background: var(--accent); }\n    .bar.hot > i { background: var(--danger); }\n    .actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }\n\n    .split { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 16px; align-items: start; }\n    table { width: 100%; border-collapse: collapse; font-size: 14px; }\n    th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid var(--line); }\n    th { color: var(--muted); font-weight: 600; font-size: 13px; }\n    td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }\n    tbody tr { cursor: pointer; }\n    tbody tr:hover, tbody tr[aria-selected=\"true\"] { background: var(--surface-2); }\n    tbody tr:focus-visible { outline-offset: -3px; }\n    .empty { padding: 18px 6px; color: var(--muted); }\n\n    .transcript { max-height: 70vh; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; }\n    .msg { max-width: 92%; display: flex; flex-direction: column; gap: 2px; }\n    .msg .who-label { font-size: 12px; color: var(--muted); }\n    .msg .bubble { padding: 9px 13px; border-radius: 12px; white-space: pre-wrap; overflow-wrap: anywhere; background: var(--surface-2); border: 1px solid var(--line); }\n    .msg.user { align-self: flex-end; align-items: flex-end; }\n    .msg.user .bubble { background: var(--user-bg); border-color: var(--user-bg); color: var(--user-text); }\n\n    @media (max-width: 860px) { .split { grid-template-columns: 1fr; } .wrap { padding: 12px; } }\n  </style>\n</head>\n<body>\n  <header class=\"top\">\n    <h1>模擬ヒアリング　講師の画面</h1>\n    <button class=\"btn\" id=\"logout\" type=\"button\" hidden>退出</button>\n  </header>\n\n  <section class=\"login-wrap\" id=\"login-view\" hidden>\n    <form class=\"card login-card\" id=\"login-form\" autocomplete=\"off\">\n      <h2>講師用の合言葉</h2>\n      <label for=\"code\">管理用の合言葉</label>\n      <input class=\"field\" id=\"code\" type=\"password\" required autocomplete=\"off\" spellcheck=\"false\">\n      <div class=\"form-error\" id=\"login-error\" role=\"alert\" hidden></div>\n      <button class=\"btn primary\" id=\"login-submit\" type=\"submit\">入室</button>\n    </form>\n  </section>\n\n  <div class=\"wrap\" id=\"dash-view\" hidden>\n    <div class=\"banner danger\" id=\"provider-error\" role=\"alert\" hidden></div>\n    <div class=\"banner danger\" id=\"limit-banner\" role=\"alert\" hidden>1日のトークン上限に達しました。全員の送信が止まっています。</div>\n    <div class=\"banner warn\" id=\"stopped-banner\" hidden>いま全員の送信を止めています。</div>\n\n    <div class=\"grid\">\n      <section class=\"card\">\n        <h2>今日の使用量（<span id=\"date\"></span>）</h2>\n        <div class=\"big\" id=\"cost\">—</div>\n        <div class=\"muted\" style=\"font-size:13px\">概算の金額（公式の単価から計算した目安）</div>\n        <dl class=\"kv\">\n          <dt>入力</dt><dd id=\"u-input\">—</dd>\n          <dt>　うちキャッシュ読み</dt><dd id=\"u-cache-read\">—</dd>\n          <dt>　うちキャッシュ書き込み</dt><dd id=\"u-cache-write\">—</dd>\n          <dt>出力</dt><dd id=\"u-output\">—</dd>\n          <dt>リクエスト数</dt><dd id=\"u-requests\">—</dd>\n        </dl>\n      </section>\n\n      <section class=\"card\">\n        <h2>1日の上限（入力＋出力）</h2>\n        <div class=\"big\"><span id=\"limit-used\">—</span> <span class=\"muted\" style=\"font-size:15px\">/ <span id=\"limit-max\">—</span></span></div>\n        <div class=\"bar\" id=\"limit-bar\" role=\"progressbar\" aria-label=\"1日のトークン上限に対する使用割合\" aria-valuemin=\"0\" aria-valuemax=\"100\"><i id=\"limit-fill\" style=\"width:0%\"></i></div>\n        <dl class=\"kv\">\n          <dt>往復の上限</dt><dd><span id=\"max-turns\">—</span> 回 / 1人・1相手</dd>\n        </dl>\n      </section>\n\n      <section class=\"card\">\n        <h2>稼働状況</h2>\n        <dl class=\"kv\" style=\"margin-top:0\">\n          <dt>AI</dt><dd id=\"provider\">—</dd>\n          <dt>モデル</dt><dd id=\"model\">—</dd>\n          <dt>保存先</dt><dd id=\"storage\">—</dd>\n        </dl>\n        <div class=\"actions\" style=\"margin-top:14px\">\n          <button class=\"btn danger\" id=\"stop-btn\" type=\"button\">全員の送信を止める</button>\n        </div>\n        <div class=\"actions\" style=\"margin-top:10px\">\n          <input class=\"field\" id=\"log-date\" type=\"date\" aria-label=\"ログの日付\">\n          <a class=\"btn\" id=\"log-link\" href=\"#\" download>ログをダウンロード</a>\n        </div>\n      </section>\n    </div>\n\n    <div class=\"split\">\n      <section class=\"card\">\n        <h2>参加者の会話（<span id=\"conv-count\">0</span>件・5秒ごとに更新）</h2>\n        <table>\n          <thead><tr><th>参加者</th><th>相手</th><th class=\"num\">往復</th><th>最後の発言</th></tr></thead>\n          <tbody id=\"conv-rows\"></tbody>\n        </table>\n        <div class=\"empty\" id=\"conv-empty\" hidden>まだ会話はありません。</div>\n      </section>\n\n      <section class=\"card\">\n        <h2 id=\"transcript-title\">会話の全文</h2>\n        <div class=\"transcript\" id=\"transcript\"><div class=\"empty\">左の一覧から会話を選んでください。</div></div>\n      </section>\n    </div>\n  </div>\n\n  <script>\n    \"use strict\";\n    const $ = (id) => document.getElementById(id);\n    const fmt = new Intl.NumberFormat(\"ja-JP\");\n    let selected = null; // { participantId, personaId }\n    let timer = null;\n\n    async function api(path, options = {}) {\n      return fetch(path, { ...options, headers: { \"Content-Type\": \"application/json\", ...(options.headers || {}) } });\n    }\n    async function errorMessage(res) {\n      try { const d = await res.json(); return d.error && d.error.message ? d.error.message : \"エラーが発生しました\"; } catch { return \"エラーが発生しました\"; }\n    }\n\n    function showLogin(message) {\n      clearInterval(timer);\n      $(\"dash-view\").hidden = true;\n      $(\"logout\").hidden = true;\n      $(\"login-view\").hidden = false;\n      $(\"login-error\").hidden = !message;\n      $(\"login-error\").textContent = message || \"\";\n      $(\"code\").focus();\n    }\n\n    function showDashboard() {\n      $(\"login-view\").hidden = true;\n      $(\"dash-view\").hidden = false;\n      $(\"logout\").hidden = false;\n      $(\"log-date\").value = new Date().toLocaleDateString(\"sv-SE\");\n      updateLogLink();\n      refresh();\n      clearInterval(timer);\n      timer = setInterval(refresh, 5000);\n    }\n\n    function updateLogLink() {\n      $(\"log-link\").href = `/api/admin/logs?date=${encodeURIComponent($(\"log-date\").value)}`;\n    }\n\n    async function refresh() {\n      const [statusRes, convRes] = await Promise.all([api(\"/api/admin/status\"), api(\"/api/admin/conversations\")]);\n      if (statusRes.status === 401 || convRes.status === 401) return showLogin(\"もう一度、管理用の合言葉を入力してください\");\n      if (statusRes.ok) renderStatus(await statusRes.json());\n      if (convRes.ok) renderConversations((await convRes.json()).conversations);\n      if (selected) loadTranscript(false);\n    }\n\n    function renderStatus(s) {\n      $(\"date\").textContent = s.date;\n      $(\"cost\").textContent = s.estimatedCostUsd === null ? \"単価不明\" : `$${s.estimatedCostUsd.toFixed(2)}`;\n      $(\"u-input\").textContent = fmt.format(s.usage.inputTokens + s.usage.cacheReadTokens + s.usage.cacheWriteTokens);\n      $(\"u-cache-read\").textContent = fmt.format(s.usage.cacheReadTokens);\n      $(\"u-cache-write\").textContent = fmt.format(s.usage.cacheWriteTokens);\n      $(\"u-output\").textContent = fmt.format(s.usage.outputTokens);\n      $(\"u-requests\").textContent = fmt.format(s.usage.requests);\n\n      const ratio = Math.min(100, Math.round((s.usage.totalTokens / s.dailyTokenLimit) * 100));\n      $(\"limit-used\").textContent = fmt.format(s.usage.totalTokens);\n      $(\"limit-max\").textContent = fmt.format(s.dailyTokenLimit);\n      $(\"limit-fill\").style.width = `${ratio}%`;\n      $(\"limit-bar\").setAttribute(\"aria-valuenow\", String(ratio));\n      $(\"limit-bar\").classList.toggle(\"hot\", ratio >= 80);\n      $(\"max-turns\").textContent = s.maxTurns;\n\n      $(\"provider\").textContent = s.provider;\n      $(\"model\").textContent = s.model;\n      $(\"storage\").textContent = s.storage === \"redis\" ? \"Redis\" : \"メモリ（再起動で消える）\";\n\n      $(\"limit-banner\").hidden = !s.limitReached;\n      $(\"stopped-banner\").hidden = !s.stopped;\n      const stopBtn = $(\"stop-btn\");\n      stopBtn.textContent = s.stopped ? \"送信を再開する\" : \"全員の送信を止める\";\n      stopBtn.className = s.stopped ? \"btn primary\" : \"btn danger\";\n      stopBtn.dataset.stopped = String(s.stopped);\n\n      const err = $(\"provider-error\");\n      err.hidden = !s.providerError;\n      err.textContent = \"\";\n      if (s.providerError) {\n        err.append(\"AIの呼び出しに失敗しています（APIキー・残高・モデル名を確認してください）\");\n        const small = document.createElement(\"small\");\n        small.textContent = `${new Date(s.providerError.at).toLocaleTimeString(\"ja-JP\")}　${s.providerError.message}`;\n        err.append(small);\n      }\n    }\n\n    function renderConversations(rows) {\n      $(\"conv-count\").textContent = rows.length;\n      $(\"conv-empty\").hidden = rows.length > 0;\n      const body = $(\"conv-rows\");\n      body.textContent = \"\";\n      for (const row of rows) {\n        const tr = document.createElement(\"tr\");\n        tr.tabIndex = 0;\n        const isSelected = selected && selected.participantId === row.participantId && selected.personaId === row.personaId;\n        tr.setAttribute(\"aria-selected\", String(Boolean(isSelected)));\n        const cells = [row.name, row.personaName, String(row.turns), new Date(row.lastAt).toLocaleTimeString(\"ja-JP\")];\n        cells.forEach((text, i) => {\n          const td = document.createElement(\"td\");\n          if (i === 2) td.className = \"num\";\n          td.textContent = text;\n          tr.append(td);\n        });\n        const open = () => { selected = { participantId: row.participantId, personaId: row.personaId, name: row.name, personaName: row.personaName }; loadTranscript(true); refresh(); };\n        tr.addEventListener(\"click\", open);\n        tr.addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\" || e.key === \" \") { e.preventDefault(); open(); } });\n        body.append(tr);\n      }\n    }\n\n    async function loadTranscript(scrollToEnd) {\n      if (!selected) return;\n      const res = await api(`/api/admin/conversations/${encodeURIComponent(selected.participantId)}/${encodeURIComponent(selected.personaId)}`);\n      const box = $(\"transcript\");\n      if (res.status === 404) {\n        box.textContent = \"\";\n        const note = document.createElement(\"div\");\n        note.className = \"empty\";\n        note.textContent = \"この会話は、参加者が「やり直す」で消しました（ログには残っています）。\";\n        box.append(note);\n        return;\n      }\n      if (!res.ok) return;\n      const data = await res.json();\n      $(\"transcript-title\").textContent = `${data.name} ↔ ${data.personaName}（${data.turns}往復）`;\n      const nearBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 80;\n      box.textContent = \"\";\n      for (const m of data.messages) {\n        const wrap = document.createElement(\"div\");\n        wrap.className = `msg ${m.role}`;\n        const label = document.createElement(\"div\");\n        label.className = \"who-label\";\n        label.textContent = `${m.role === \"user\" ? data.name : data.personaName}　${new Date(m.at).toLocaleTimeString(\"ja-JP\")}`;\n        const bubble = document.createElement(\"div\");\n        bubble.className = \"bubble\";\n        bubble.textContent = m.text;\n        wrap.append(label, bubble);\n        box.append(wrap);\n      }\n      if (scrollToEnd || nearBottom) box.scrollTop = box.scrollHeight;\n    }\n\n    $(\"login-form\").addEventListener(\"submit\", async (event) => {\n      event.preventDefault();\n      $(\"login-submit\").disabled = true;\n      try {\n        const res = await api(\"/api/admin/login\", { method: \"POST\", body: JSON.stringify({ code: $(\"code\").value }) });\n        if (!res.ok) { $(\"login-error\").textContent = await errorMessage(res); $(\"login-error\").hidden = false; return; }\n        $(\"code\").value = \"\";\n        showDashboard();\n      } catch {\n        $(\"login-error\").textContent = \"通信に失敗しました\"; $(\"login-error\").hidden = false;\n      } finally {\n        $(\"login-submit\").disabled = false;\n      }\n    });\n\n    $(\"stop-btn\").addEventListener(\"click\", async () => {\n      const stopping = $(\"stop-btn\").dataset.stopped !== \"true\";\n      if (stopping && !window.confirm(\"全員の送信を止めます。よろしいですか？（あとで再開できます）\")) return;\n      await api(\"/api/admin/stop\", { method: \"POST\", body: JSON.stringify({ stopped: stopping }) });\n      refresh();\n    });\n\n    $(\"log-date\").addEventListener(\"change\", updateLogLink);\n    $(\"logout\").addEventListener(\"click\", async () => { await api(\"/api/admin/logout\", { method: \"POST\", body: \"{}\" }); showLogin(); });\n\n    (async function init() {\n      const res = await api(\"/api/admin/status\");\n      if (res.ok) showDashboard(); else showLogin();\n    })();\n  </script>\n</body>\n</html>\n";
